 1	pub fn atoi_i32(input: &str) -> i32 {
 2	    let bytes = input.as_bytes();
 3	    let mut index = 0;
 4	
 5	    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
 6	        index += 1;
 7	    }
 8	
 9	    let mut negative = false;
10	    if index < bytes.len() {
11	        match bytes[index] {
12	            b'+' => index += 1,
13	            b'-' => {
14	                negative = true;
15	                index += 1;
16	            }
17	            _ => {}
18	        }
19	    }
20	
21	    let digits_start = index;
22	    let mut magnitude = 0_u128;
23	    while index < bytes.len() && bytes[index].is_ascii_digit() {
24	        let digit = u128::from(bytes[index] - b'0');
25	        magnitude = magnitude.saturating_mul(10).saturating_add(digit);
26	        index += 1;
27	    }
28	
29	    if index == digits_start {
30	        return 0;
31	    }
32	
33	    let signed = if negative {
34	        let negative_limit = (i64::MAX as u128) + 1;
35	        if magnitude >= negative_limit {
36	            i64::MIN
37	        } else {
38	            -(magnitude as i64)
39	        }
40	    } else if magnitude >= i64::MAX as u128 {
41	        i64::MAX
42	    } else {
43	        magnitude as i64
44	    };
45	
46	    signed as i32
47	}
