15	fn main() -> io::Result<()> {
16	    let args: Vec<String> = env::args().collect();
17	    Inflector::initialize();
18	
19	    if args.len() > 2 {
20	        let num = atoi_i32(&args[1]);
21	        let word = &args[2];
22	        let mut stdout = io::stdout().lock();
23	
24	        write_line(&mut stdout, &Inflector::pluralize(word))?;
25	        write_line(&mut stdout, &Inflector::ordinalize(num))?;
26	        write_line(&mut stdout, &Inflector::camelize(word, true))?;
27	        write_line(&mut stdout, &Inflector::camelize(word, false))?;
28	        write_line(&mut stdout, &Inflector::titleize(word))?;
29	        write_line(&mut stdout, &Inflector::capitalize(word))?;
30	        write_line(&mut stdout, &Inflector::truncate(word, 5, "..."))?;
31	        write_line(&mut stdout, &Inflector::truncate(word, 10, "~"))?;
32	        write_line(&mut stdout, &Inflector::parameterize(word))?;
33	        write_line(
34	            &mut stdout,
35	            &Inflector::parameterize_with_separator(word, "_"),
36	        )?;
37	        write_line(&mut stdout, if Inflector::is_plural(word) { b"1" } else { b"0" })?;
38	    }
39	
40	    Ok(())
41	}

  1	pub struct Inflector;
  2	
  3	impl Inflector {
  4	    pub fn initialize() {}
  5	
  6	    pub fn pluralize(word: &str) -> Vec<u8> {
  7	        if word.is_empty() {
  8	            return Vec::new();
  9	        }
 10	
 11	        let mut output = Vec::with_capacity(word.len() + 1);
 12	        output.extend_from_slice(word.as_bytes());
 13	        output.push(b's');
 14	        output
 15	    }
 16	
 17	    pub fn ordinalize(number: i32) -> Vec<u8> {
 18	        let suffix = match number % 100 {
 19	            11..=13 => "th",
 20	            _ => match number % 10 {
 21	                1 => "st",
 22	                2 => "nd",
 23	                3 => "rd",
 24	                _ => "th",
 25	            },
 26	        };
 27	
 28	        format!("{number}{suffix}").into_bytes()
 29	    }
 30	
 31	    pub fn camelize(word: &str, lower_camel: bool) -> Vec<u8> {
 32	        let mut output = Vec::with_capacity(word.len());
 33	        let mut uppercase_next = !lower_camel;
 34	
 35	        for &byte in word.as_bytes() {
 36	            if byte == b'_' {
 37	                uppercase_next = true;
 38	                continue;
 39	            }
 40	
 41	            if uppercase_next {
 42	                output.push(byte.to_ascii_uppercase());
 43	                uppercase_next = false;
 44	            } else {
 45	                output.push(byte);
 46	            }
 47	        }
 48	
 49	        output
 50	    }
 51	
 52	    pub fn titleize(word: &str) -> Vec<u8> {
 53	        let mut output = Self::ascii_lowercase(word.as_bytes());
 54	        let mut uppercase_next = true;
 55	
 56	        for byte in &mut output {
 57	            if uppercase_next {
 58	                *byte = byte.to_ascii_uppercase();
 59	            }
 60	            uppercase_next = *byte == b' ';
 61	        }
 62	
 63	        output
 64	    }
 65	
 66	    pub fn capitalize(word: &str) -> Vec<u8> {
 67	        let mut output = Self::ascii_lowercase(word.as_bytes());
 68	        if let Some(first) = output.first_mut() {
 69	            *first = first.to_ascii_uppercase();
 70	        }
 71	        output
 72	    }
 73	
 74	    pub fn truncate(word: &str, limit: usize, ending: &str) -> Vec<u8> {
 75	        let bytes = word.as_bytes();
 76	        if bytes.len() <= limit {
 77	            return bytes.to_vec();
 78	        }
 79	
 80	        let ending_bytes = ending.as_bytes();
 81	        if limit <= ending_bytes.len() {
 82	            return ending_bytes[..limit].to_vec();
 83	        }
 84	
 85	        let visible = limit - ending_bytes.len();
 86	        let mut output = Vec::with_capacity(limit);
 87	        output.extend_from_slice(&bytes[..visible]);
 88	        output.extend_from_slice(ending_bytes);
 89	        output
 90	    }
 91	
 92	    pub fn parameterize(word: &str) -> Vec<u8> {
 93	        Self::parameterize_with_separator(word, "-")
 94	    }
 95	
 96	    pub fn parameterize_with_separator(word: &str, separator: &str) -> Vec<u8> {
 97	        let separator_bytes = separator.as_bytes();
 98	        let mut output = Vec::with_capacity(word.len());
 99	
100	        for &byte in word.as_bytes() {
101	            if byte.is_ascii_alphanumeric() {
102	                output.push(byte.to_ascii_lowercase());
103	            } else if byte == b' ' {
104	                output.extend_from_slice(separator_bytes);
105	            }
106	        }
107	
108	        Self::trim_separator(output, separator_bytes)
109	    }
110	
111	    pub fn is_plural(word: &str) -> bool {
112	        matches!(word.as_bytes().last(), Some(b's'))
113	    }
114	
115	    fn ascii_lowercase(bytes: &[u8]) -> Vec<u8> {
116	        bytes.iter().map(u8::to_ascii_lowercase).collect()
117	    }
118	
119	    fn trim_separator(mut bytes: Vec<u8>, separator: &[u8]) -> Vec<u8> {
120	        if separator.is_empty() || bytes.is_empty() {
121	            return bytes;
122	        }
123	
124	        let mut start = 0;
125	        while bytes[start..].starts_with(separator) {
126	            start += separator.len();
127	            if start >= bytes.len() {
128	                return Vec::new();
129	            }
130	        }
131	
132	        let mut end = bytes.len();
133	        while end >= start + separator.len() && bytes[..end].ends_with(separator) {
134	            end -= separator.len();
135	        }
136	
137	        if start == 0 && end == bytes.len() {
138	            bytes
139	        } else {
140	            bytes.drain(..start);
141	            bytes.truncate(end - start);
142	            bytes
143	        }
144	    }
145	}
